response:
**Gates before launch.** I run these in order and stop at the first one that fails. First, I confirm that spe/predictions/r04.yaml and spe/plans/r04.md are in HEAD. Second, I run `python3 spe/evals/graders/grade.py --selftest`. The oracle (answers.json fed back in as results) must score 1.0 on label.category and label.priority. The empty answer set and the wrong answer set must both score 0. Third, I count the entries in spe/evals/tasks/answers.json and check there are 50. Fourth, I stage the 50 tickets under /tmp/triage-spe/r04/tickets with their label fields removed. I grep the staged files to make sure no reference label is left in them. Fifth, I regrade round 3's saved outputs with this round's grade.py as a control. If any round 3 number changes, the grader changed. In that case I log it in spe/failures.md and halt before any trial runs. Sixth, I do a dry run of the script with `only` set to 3 cells and `trialsPerCell: 1`. It must return valid rows, grades, judge scores and an audit result. The dry run also measures what one trial and one judge call cost. I put those numbers in `estCostUsd`. I set `spendCapUsd` to $40 minus what the gates spent. If the projected full run would go over that cap, I stop and ask you. I do not let the script skip trials to fit. Last, I commit spe/evals/harness/r04-workflow.js locally with a plain message and launch.

**Defaults I chose:**
- The project notes say the eval set has 40 tickets, but the approved plan says 50. I assume round 4 added 10 reference tickets. The count gate halts if answers.json still holds 40.
- I assume the triage runner and grade.py accept the flags shown in the script. The dry run will catch it if they do not.

**Launch arguments (full run):**
```json
{
  "configs": ["B", "C2"],
  "tickets": ["<the 50 staged ticket ids>"],
  "expectTickets": 50,
  "trialsPerCell": 5,
  "runner": "node scripts/run-triage.js",
  "spendCapUsd": "<40 minus gate spend>",
  "estCostUsd": { "trial": "<from dry run>", "cellAgent": "<from dry run>", "judge": "<from dry run>" },
  "topupPerCell": 3,
  "topupMaxTrials": 40,
  "transcriptDir": "<workflow transcript dir>"
}
```

**spe/evals/harness/r04-workflow.js**
```js
export const meta = {
  name: "spe-triage-eval",
  description: "SPE eval for the triage agent. Runs each config on the staged tickets, grades labels with grade.py, tops up split cells, judges reply tone with Opus, then runs failure analysis and a completeness critic.",
  phases: ["Trials", "Audit", "Grade", "Top-up", "Judge", "Synthesis"],
};

// The round lives here only. Paths and prompts derive from it.
const ROUND = 4;
const RR = `r${String(ROUND).padStart(2, "0")}`;

// ---------- Arguments ----------
const A = typeof args === "object" && args ? args : {};
const CONFIGS = A.configs ?? ["B", "C2"]; // B: 12-line prompt, 6 tools. C2: 12-line prompt, 3 merged tools plus check_status.
const TICKETS = A.tickets ?? []; // ids staged at STAGE/tickets/<id>.json with labels removed
const EXPECT_TICKETS = A.expectTickets ?? 50;
const TRIALS = A.trialsPerCell ?? 5;
const STAGE = A.stageDir ?? `/tmp/triage-spe/${RR}`;
const RUNNER = A.runner;
const CAP = A.spendCapUsd;
const EST = { trial: 0.03, cellAgent: 0.15, audit: 0.1, grade: 0.3, judge: 0.2, synth: 0.6, ...(A.estCostUsd ?? {}) };
const TOPUP_PER_CELL = A.topupPerCell ?? 3;
const TOPUP_MAX = A.topupMaxTrials ?? 40;
const CONCURRENCY = A.concurrency ?? 8;
const TRANSCRIPT_DIR = A.transcriptDir ?? null;
const ONLY = Array.isArray(A.only) ? new Set(A.only) : null; // dry run: ["B:T-1007", "C2:T-1007", "C2:T-1031"]
const SEED = A.seed ?? ROUND;
const MODEL = { runner: A.runnerAgentModel ?? "opus", grader: "opus", judge: "opus" };

if (!RUNNER) throw new Error("args.runner is required.");
if (typeof CAP !== "number" || CAP <= 0) throw new Error("args.spendCapUsd is required.");
if (!ONLY && TICKETS.length !== EXPECT_TICKETS) {
  throw new Error(`Expected ${EXPECT_TICKETS} tickets, got ${TICKETS.length}. Halting.`);
}

// ---------- Cells ----------
const cells = [];
for (const config of CONFIGS) {
  for (const ticket of TICKETS) {
    const key = `${config}:${ticket}`;
    if (!ONLY || ONLY.has(key)) cells.push({ config, ticket, key });
  }
}
const runTickets = [...new Set(cells.map((c) => c.ticket))];

// ---------- Budget ----------
// Two pools. Trials cannot spend the money held back for grading, judging, and synthesis.
// Runner costs are measured from the runner output. Agent costs are estimates from estCostUsd.
const HOLDBACK = EST.judge * runTickets.length + EST.grade * CONFIGS.length * 2 + EST.audit * 2 + EST.synth * 2;
const pools = {
  trials: { cap: CAP - HOLDBACK, spent: 0, reserved: 0 },
  evals: { cap: HOLDBACK, spent: 0, reserved: 0 },
};
if (pools.trials.cap <= 0) throw new Error(`Cap $${CAP} does not cover the eval holdback of $${HOLDBACK.toFixed(2)}.`);
const skips = [];

function reserve(pool, usd, what) {
  const p = pools[pool];
  if (p.spent + p.reserved + usd > p.cap) {
    skips.push({ what, usd, pool });
    log(`SKIP ${what}: $${usd.toFixed(2)} would cross the ${pool} cap.`);
    return false;
  }
  p.reserved += usd;
  return true;
}
function settle(pool, reserved, actual) {
  pools[pool].reserved -= reserved;
  pools[pool].spent += actual;
}
function reserveTrials(want, what) {
  const p = pools.trials;
  const room = p.cap - p.spent - p.reserved - EST.cellAgent;
  const n = Math.max(0, Math.min(want, Math.floor(room / EST.trial)));
  if (n < want) {
    skips.push({ what, trials: want - n, pool: "trials" });
    log(`SKIP ${want - n} of ${want} trials for ${what}: spend cap.`);
  }
  if (n === 0) return { n: 0, usd: 0 };
  const usd = EST.cellAgent + n * EST.trial;
  p.reserved += usd;
  return { n, usd };
}

// ---------- Helpers ----------
const keyOf = (r) => `${r.config}:${r.ticket_id}:${r.trial}`;
const mean = (xs) => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : null);
const median = (xs) => {
  if (!xs.length) return null;
  const s = xs.slice().sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};
function rng(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rand = rng(SEED);
function shuffle(xs) {
  const a = xs.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}
async function inWaves(items, fn) {
  const out = [];
  for (let i = 0; i < items.length; i += CONCURRENCY) {
    const wave = items.slice(i, i + CONCURRENCY);
    out.push(...(await parallel(wave.map((it) => () => fn(it)))));
  }
  return out;
}

// ---------- Schemas ----------
const ROW = {
  type: "object",
  required: ["trial", "status"],
  properties: {
    trial: { type: "integer" },
    status: { type: "string", enum: ["completed", "harness_error", "rate_limited"] },
    category: { type: "string" },
    priority: { type: "string" },
    reply: { type: "string" },
    runtime_ms: { type: "number" },
    tool_calls: { type: "integer" },
    tool_errors: { type: "integer" },
    input_tokens: { type: "integer" },
    output_tokens: { type: "integer" },
    cost_usd: { type: "number" },
    error: { type: "string" },
  },
};
const CELL_SCHEMA = {
  type: "object",
  required: ["rows", "commands_run", "paths_read"],
  properties: {
    rows: { type: "array", items: ROW },
    commands_run: { type: "array", items: { type: "string" } },
    paths_read: { type: "array", items: { type: "string" } },
  },
};
const AUDIT_SCHEMA = {
  type: "object",
  required: ["peeked", "labels_checked"],
  properties: {
    labels_checked: { type: "integer" },
    peeked: {
      type: "array",
      items: { type: "object", required: ["label", "evidence"], properties: { label: { type: "string" }, evidence: { type: "string" } } },
    },
  },
};
const GRADE_SCHEMA = {
  type: "object",
  required: ["selftest_ok", "rows"],
  properties: {
    selftest_ok: { type: "boolean" },
    rows: {
      type: "array",
      items: {
        type: "object",
        required: ["ticket_id", "trial", "category_ok", "priority_ok"],
        properties: {
          ticket_id: { type: "string" },
          trial: { type: "integer" },
          category_ok: { type: "boolean" },
          priority_ok: { type: "boolean" },
        },
      },
    },
    errors: { type: "array", items: { type: "string" } },
  },
};
const JUDGE_SCHEMA = {
  type: "object",
  required: ["scores"],
  properties: {
    scores: {
      type: "array",
      items: {
        type: "object",
        required: ["id", "score", "pass"],
        properties: { id: { type: "string" }, score: { type: "number" }, pass: { type: "boolean" }, note: { type: "string" } },
      },
    },
  },
};
const ANALYSIS_SCHEMA = {
  type: "object",
  required: ["groups", "config_contrast"],
  properties: {
    groups: {
      type: "array",
      items: {
        type: "object",
        required: ["f_id", "name", "kind", "what", "how_to_spot", "seen_in", "fix", "grader_suspect"],
        properties: {
          f_id: { type: "string" },
          name: { type: "string" },
          kind: { type: "string", enum: ["agent", "grader", "harness", "task"] },
          what: { type: "string" },
          how_to_spot: { type: "string" },
          seen_in: { type: "array", items: { type: "string" } },
          fix: { type: "string" },
          grader_suspect: { type: "boolean" },
        },
      },
    },
    config_contrast: { type: "string" },
  },
};
const CRITIC_SCHEMA = {
  type: "object",
  required: ["complete", "gaps"],
  properties: {
    complete: { type: "boolean" },
    gaps: {
      type: "array",
      items: { type: "object", required: ["what", "severity", "fix"], properties: { what: { type: "string" }, severity: { type: "string", enum: ["blocks_scoring", "weakens", "note"] }, fix: { type: "string" } } },
    },
  },
};

// ---------- Trials ----------
// Trials may read only STAGE and the runner output. Any reference to spe/ or a grader file voids the trial.
const FORBIDDEN = /(^|[\s"'=\/])spe\/|answers\.json|grade\.py|judge\.md/;

function cellPrompt(c, n, offset) {
  return [
    `You are a trial runner for an evaluation of the triage support agent, config ${c.config}.`,
    `Run exactly this command from the repository root:`,
    `${RUNNER} --config ${c.config} --ticket ${STAGE}/tickets/${c.ticket}.json --trials ${n} --trial-offset ${offset} --out ${STAGE}/out/${c.config}/${c.ticket}`,
    `It prints one JSON line per trial. Return one row per line, copied field for field. Do not fix, rerun, or judge the agent's answers.`,
    `If the command fails or hits a rate limit, return rows with status "harness_error" or "rate_limited" and the error text.`,
    `You may read only files under ${STAGE}/. Do not open, list, grep, or cat anything under spe/.`,
    `List every command you ran in commands_run and every file path you read in paths_read.`,
  ].join("\n");
}

let rows = [];

async function runCell(c, want, offset, source, label, phaseName) {
  const r = reserveTrials(want, label);
  if (r.n === 0) return [];
  let res;
  try {
    res = await agent(cellPrompt(c, r.n, offset), { label, phase: phaseName, schema: CELL_SCHEMA, model: MODEL.runner });
  } catch (e) {
    settle("trials", r.usd, EST.cellAgent);
    return Array.from({ length: r.n }, (_, k) => ({
      config: c.config, ticket_id: c.ticket, trial: offset + k, status: "harness_error", error: String(e), source, label, void: null,
    }));
  }
  const got = (res.rows ?? []).slice(0, r.n);
  while (got.length < r.n) got.push({ trial: offset + got.length, status: "harness_error", error: "runner returned fewer rows than requested" });
  settle("trials", r.usd, EST.cellAgent + got.reduce((s, x) => s + (Number.isFinite(x.cost_usd) ? x.cost_usd : x.status === "completed" ? EST.trial : 0), 0));
  const peek = [...(res.commands_run ?? []), ...(res.paths_read ?? [])].find((s) => FORBIDDEN.test(s));
  return got.map((x) => ({ ...x, config: c.config, ticket_id: c.ticket, source, label, void: peek ? `self-report: ${peek}` : null }));
}

phase("Trials");
log(`${RR}: ${cells.length} cells x ${TRIALS} trials. Cap $${CAP}. Trial pool $${pools.trials.cap.toFixed(2)}, eval holdback $${HOLDBACK.toFixed(2)}.`);
rows = (await inWaves(cells, (c) => runCell(c, TRIALS, 0, "base", `base ${c.key}`, "Trials"))).flat();

// A harness error or rate limit is not a model failure. Refill those trials once.
const refill = cells
  .map((c) => ({ c, n: TRIALS - rows.filter((r) => r.config === c.config && r.ticket_id === c.ticket && r.status === "completed").length }))
  .filter((x) => x.n > 0);
if (refill.length) {
  log(`Refill: ${refill.length} cells lost trials to harness errors or rate limits.`);
  rows = rows.concat((await inWaves(refill, ({ c, n }) => runCell(c, n, 100, "base", `refill ${c.key}`, "Trials"))).flat());
}

// ---------- Audit ----------
async function audit(batch, tag, phaseName) {
  if (!TRANSCRIPT_DIR) {
    log(`Audit ${tag}: no transcriptDir given. Peek check uses self-report only.`);
    return;
  }
  const labels = [...new Set(batch.map((r) => r.label))];
  if (!labels.length || !reserve("evals", EST.audit, `audit ${tag}`)) return;
  try {
    const res = await agent(
      [
        `Search the agent transcripts under ${TRANSCRIPT_DIR} for the runs with the labels below.`,
        `Report each label whose transcript shows a read, list, grep, or cat of any path under spe/, or of answers.json, grade.py, or judge.md.`,
        `Report only evidence you saw, with the matching line. Do not edit any file.`,
        `Labels:`,
        ...labels,
      ].join("\n"),
      { label: `audit ${tag}`, phase: phaseName, schema: AUDIT_SCHEMA, model: MODEL.grader },
    );
    for (const p of res.peeked ?? []) {
      for (const r of batch) if (r.label === p.label && !r.void) r.void = `transcript: ${p.evidence}`;
    }
    log(`Audit ${tag}: checked ${res.labels_checked} of ${labels.length} labels. ${(res.peeked ?? []).length} peeked.`);
  } finally {
    settle("evals", EST.audit, EST.audit);
  }
}

phase("Audit");
await audit(rows, "base", "Audit");

// ---------- Grade ----------
// Code grader first. grade.py checks label.category and label.priority against answers.json.
function gradePrompt(config) {
  return [
    `Run these commands from the repository root and report their output. Do not edit any file.`,
    `1. python3 spe/evals/graders/grade.py --selftest`,
    `2. python3 spe/evals/graders/grade.py --answers spe/evals/tasks/answers.json --results ${STAGE}/out/${config} --format json`,
    `Set selftest_ok to true only if command 1 exits 0.`,
    `Return one row per trial file graded by command 2, with ticket_id, trial, category_ok, and priority_ok copied from its output. Put any grader error in errors.`,
  ].join("\n");
}

async function gradeAll(tag, phaseName) {
  const results = await parallel(
    CONFIGS.map((config) => async () => {
      if (!reserve("evals", EST.grade, `grade ${config} ${tag}`)) return { config, selftest_ok: null, rows: [] };
      try {
        const res = await agent(gradePrompt(config), { label: `grade ${config} ${tag}`, phase: phaseName, schema: GRADE_SCHEMA, model: MODEL.grader });
        return { config, ...res };
      } catch (e) {
        return { config, selftest_ok: null, rows: [], errors: [String(e)] };
      } finally {
        settle("evals", EST.grade, EST.grade);
      }
    }),
  );
  for (const g of results) {
    if (g.selftest_ok !== true) return `Grader selftest failed or did not run for ${g.config} (${tag}).`;
    if (g.errors?.length) log(`Grader errors for ${g.config}: ${g.errors.join(" | ")}`);
    const m = new Map(g.rows.map((x) => [`${g.config}:${x.ticket_id}:${x.trial}`, x]));
    for (const r of rows) {
      if (r.config !== g.config || r.status !== "completed") continue;
      const x = m.get(keyOf(r));
      r.grade = x ? { category_ok: x.category_ok, priority_ok: x.priority_ok, label_ok: x.category_ok && x.priority_ok } : null;
    }
  }
  return null;
}

const usable = (r) => r.status === "completed" && !r.void && r.grade;

function partialRecord(status, reason) {
  return {
    round: ROUND, status, reason, dry_run: !!ONLY, spend: pools, skips,
    voids: rows.filter((r) => r.void).map((r) => ({ key: keyOf(r), why: r.void })),
    rows: rows.map(({ reply, ...rest }) => rest),
  };
}

phase("Grade");
let halt = await gradeAll("base", "Grade");
if (halt) {
  log(`HALT: ${halt}`);
  return partialRecord("halted", halt);
}

// ---------- Top-up ----------
// Split cells get extra trials. Headline metrics use base trials only, so top-ups do not overweight split cells.
phase("Top-up");
const split = cells.filter((c) => {
  const g = rows.filter((r) => r.source === "base" && r.config === c.config && r.ticket_id === c.ticket && usable(r));
  const pass = g.filter((r) => r.grade.label_ok).length;
  return g.length > 0 && pass > 0 && pass < g.length;
});
let room = TOPUP_MAX;
const topupPlan = [];
for (const c of split) {
  const n = Math.min(TOPUP_PER_CELL, room);
  if (n <= 0) {
    skips.push({ what: `topup ${c.key}`, trials: TOPUP_PER_CELL, pool: "topup cap" });
    continue;
  }
  room -= n;
  topupPlan.push({ c, n });
}
log(`Top-up: ${split.length} split cells. Running ${topupPlan.length} of them, cap ${TOPUP_MAX} trials.`);
if (topupPlan.length) {
  const topRows = (await inWaves(topupPlan, ({ c, n }) => runCell(c, n, 200, "topup", `topup ${c.key}`, "Top-up"))).flat();
  rows = rows.concat(topRows);
  await audit(topRows, "topup", "Top-up");
  halt = await gradeAll("topup", "Top-up");
  if (halt) {
    log(`HALT: ${halt}`);
    return partialRecord("halted", halt);
  }
}

// ---------- Judge ----------
// Opus judges reply tone only. No judge from another model family is available, so tone results share Claude's blind spots.
phase("Judge");
log("Judge note: the judge is Opus, the same family as the trial model.");
await inWaves(runTickets, async (t) => {
  const items = shuffle(rows.filter((r) => r.ticket_id === t && usable(r) && r.reply));
  if (!items.length) return;
  const ids = items.map((row, i) => ({ id: `R${i + 1}`, row }));
  if (!reserve("evals", EST.judge, `judge ${t}`)) return;
  try {
    const res = await agent(
      [
        `You are grading the tone of draft support replies. Read the rubric at spe/evals/graders/judge.md and follow it exactly.`,
        `Read the ticket at ${STAGE}/tickets/${t}.json.`,
        `Score each reply below on tone only. Do not score the category or the priority. The replies come from different systems in random order.`,
        ...ids.map((x) => `--- ${x.id} ---\n${x.row.reply}`),
      ].join("\n\n"),
      { label: `judge ${t}`, phase: "Judge", schema: JUDGE_SCHEMA, model: MODEL.judge },
    );
    for (const s of res.scores ?? []) {
      const m = ids.find((x) => x.id === s.id);
      if (m) m.row.tone = { score: s.score, pass: s.pass, note: s.note ?? "" };
    }
  } catch (e) {
    log(`Judge ${t} failed: ${e}`);
  } finally {
    settle("evals", EST.judge, EST.judge);
  }
});

// ---------- Synthesis ----------
phase("Synthesis");
function stats(config, sources) {
  const all = rows.filter((r) => r.config === config && sources.includes(r.source));
  const done = all.filter(usable);
  const judged = done.filter((r) => r.tone);
  const b = (x) => (x ? 1 : 0);
  return {
    trials_run: all.length,
    completed: all.filter((r) => r.status === "completed").length,
    harness_errors: all.filter((r) => r.status === "harness_error").length,
    rate_limited: all.filter((r) => r.status === "rate_limited").length,
    voided: all.filter((r) => r.void).length,
    ungraded: all.filter((r) => r.status === "completed" && !r.void && !r.grade).length,
    scored: done.length,
    category_acc: mean(done.map((r) => b(r.grade.category_ok))),
    priority_acc: mean(done.map((r) => b(r.grade.priority_ok))),
    label_acc: mean(done.map((r) => b(r.grade.label_ok))),
    tone_judged: judged.length,
    tone_pass_rate: mean(judged.map((r) => b(r.tone.pass))),
    tone_mean: mean(judged.map((r) => r.tone.score)),
    runtime_ms_median: median(done.map((r) => r.runtime_ms).filter(Number.isFinite)),
    tool_calls_mean: mean(done.map((r) => r.tool_calls).filter(Number.isFinite)),
    tool_errors_per_trial: mean(done.map((r) => r.tool_errors).filter(Number.isFinite)),
    tokens_mean: mean(done.map((r) => (r.input_tokens ?? 0) + (r.output_tokens ?? 0))),
    runner_cost_usd: all.reduce((s, r) => s + (Number.isFinite(r.cost_usd) ? r.cost_usd : 0), 0),
  };
}
const headline = Object.fromEntries(CONFIGS.map((c) => [c, stats(c, ["base"])]));
const topupStats = Object.fromEntries(CONFIGS.map((c) => [c, stats(c, ["topup"])]));

const failing = rows
  .filter((r) => usable(r) && (!r.grade.label_ok || (r.tone && !r.tone.pass)))
  .map((r) => `${keyOf(r)} [${r.source}] category=${r.category} priority=${r.priority} category_ok=${r.grade.category_ok} priority_ok=${r.grade.priority_ok} tone=${r.tone ? r.tone.score : "na"}${r.tone?.note ? ` (${r.tone.note})` : ""}`);

const runRecord = {
  configs: CONFIGS, cells: cells.length, trials_per_cell: TRIALS, headline, topup: topupStats,
  split_cells: split.map((c) => c.key), skips, spend: pools,
  voids: rows.filter((r) => r.void).map((r) => ({ key: keyOf(r), why: r.void })),
  unjudged: rows.filter((r) => usable(r) && !r.tone).map(keyOf),
};

const [analysis, critic] = await parallel([
  async () => {
    if (!reserve("evals", EST.synth, "failure analysis")) return null;
    try {
      return await agent(
        [
          `You are doing failure analysis for ${RR} of the SPE loop on the triage agent.`,
          `The configs differ in one thing. B has 6 tools. C2 has 3 merged tools plus a separate check_status tool. Both use the 12-line prompt.`,
          `Read spe/failures.md for the existing F-numbered failure types. You may read spe/evals/tasks/answers.json and the trial files under ${STAGE}/out/ to compare expected and actual output.`,
          `Group the failing trials below. For each group give an existing F id or "new", a name, the kind, what happened, how to spot it, the trial keys where it was seen, and a proposed fix. Mark any group that looks like a grader bug. Do not edit any file.`,
          `Headline metrics (base trials): ${JSON.stringify(headline)}`,
          `Failing trials:\n${failing.join("\n") || "none"}`,
        ].join("\n\n"),
        { label: "failure analysis", phase: "Synthesis", schema: ANALYSIS_SCHEMA, model: MODEL.grader },
      );
    } finally {
      settle("evals", EST.synth, EST.synth);
    }
  },
  async () => {
    if (!reserve("evals", EST.synth, "completeness critic")) return null;
    try {
      return await agent(
        [
          `You are the completeness critic for ${RR} of the SPE eval on the triage agent.`,
          `Read the approved plan at spe/plans/${RR}.md. Compare it with the run record below.`,
          `List every gap. Look for planned cells or trials that did not run, skipped trials, voided trials, ungraded trials, unjudged replies, grader errors, missing metrics, and spend near the cap.`,
          `Say whether the record is complete enough to score each planned metric. Do not edit any file.`,
          `Run record: ${JSON.stringify(runRecord)}`,
        ].join("\n\n"),
        { label: "completeness critic", phase: "Synthesis", schema: CRITIC_SCHEMA, model: MODEL.grader },
      );
    } finally {
      settle("evals", EST.synth, EST.synth);
    }
  },
]);

log(`Done. Spend: trials $${pools.trials.spent.toFixed(2)}, evals $${pools.evals.spent.toFixed(2)} (agent costs estimated). Skips: ${skips.length}.`);

// Close-out copies STAGE/out to spe/evals/results/<round>/ and writes the prediction log and failures from this record.
return {
  round: ROUND,
  status: "complete",
  dry_run: !!ONLY,
  ...runRecord,
  spend_note: "Runner costs are measured. Agent costs use estCostUsd from the dry run.",
  judge_note: "Opus judge, same model family as the trials. No cross-family judge was available.",
  analysis,
  critic,
  rows: rows.map(({ reply, ...rest }) => rest),
};
